  actual: () => [["#[cfg(unix)]", "#[cfg", "unix"], ["#![allow(non_snake_case)]", "#![allow", "non_snake_case"]].map(([line, opening, name]) => [opening, name].map((word) => colorOf("a.rs", [line], { word }))),
  expected: [["tok-kw", "tok-var"], ["tok-kw", "tok-var"]],
},
{
  label: "色分け: Rust のマクロ assert! / matches! / vec! は ! ごと関数になり、a!=b の a は変数のまま",
  actual: () => ["assert!", "matches!", "vec!", "a"].map((word) => colorOf("a.rs", ["assert!(a!=b); matches!(x, y); vec![1];"], { word })),
  expected: ["tok-fn", "tok-fn", "tok-fn", "tok-var"],
},

const tokenAt = (cursor, grammar) => {
  const isYamlKeyPosition = grammar.keys === true && cursor.lineStart;
  const key = isYamlKeyPosition ? matchAt(YamlKey, cursor) : null;
  if (key) return Token("tok-key", key);
  const quoted = quotedAt(cursor, grammar);
  if (quoted) return quoted;
  if (grammar.css === true) return cssTokenAt(cursor);
  const rust = grammar.rust === true ? rustTokenAt(cursor) : null;
  if (rust) return rust;
  const variable = grammar.variables === true ? matchAt(ShellVariable, cursor) : null;
  if (variable) return Token("tok-var", variable);
  const jsx = grammar.jsx === true ? jsxTagInExpressionAt(cursor) : null;
  if (jsx) return jsx;
  return wordAt(cursor, grammar);
};

/** Rust の、文字列・コメント・数値・名前のほかの字句(生文字列・文字リテラル・ライフタイム・属性・マクロ)。どれでもなければ null。 */
const rustTokenAt = (cursor) => {
  const raw = rustRawStringAt(cursor);
  if (raw) return raw;
  const char = matchAt(RustChar, cursor);
  if (char) return Token("tok-str", char);
  const lifetime = matchAt(RustLifetime, cursor);
  if (lifetime) return Token("tok-type", lifetime);
  const attribute = matchAt(RustAttribute, cursor);
  if (attribute) return Token("tok-kw", attribute);
  const macro = matchAt(RustMacro, cursor);
  return macro ? Token("tok-fn", macro) : null;
};

/** 位置から、`from` 以降で最初に来る閉じ記号 `close` までを 1 字句にする。閉じずに行が終わったら、閉じ記号を次の行へ持ち越す。 */
const delimitedAt = (cursor, { cls, from, close }) => {
  const end = cursor.text.indexOf(close, from);
  return end >= 0 ? Token(cls, cursor.text.slice(cursor.at, end + close.length)) : Token(cls, restOfLine(cursor), close);
};

const commentAt = (cursor, grammar) => {
  const { text, at } = cursor;
  const block = grammar.block;
  const isBlockCommentStart = block !== undefined && text.startsWith(block[0], at);
  if (isBlockCommentStart) return delimitedAt(cursor, { cls: "tok-com", from: at + block[0].length, close: block[1] });
  const isLineCommentStart = grammar.comment !== undefined && text.startsWith(grammar.comment, at);
  // `#` は Python 以外では行頭か空白の直後だけコメントにする(シェルの `$#`・URL の `#` を取り違えない)。
  const isHashAllowedHere = grammar.comment !== "#" || grammar.hashAnywhere === true || /\s/.test(cursor.prev);
  const isComment = isLineCommentStart && isHashAllowedHere;
  return isComment ? Token("tok-com", restOfLine(cursor)) : null;
};

/** Rust の生文字列。中の `\` はエスケープにしない。生文字列でなければ null。 */
const rustRawStringAt = (cursor) => {
  const opening = matchAt(RustRawStringStart, cursor);
  if (!opening) return null;
  const hashes = opening.slice(opening.indexOf("r") + 1, -1);
  return delimitedAt(cursor, { cls: "tok-str", from: cursor.at + opening.length, close: `"${hashes}` });
};
